package com.google.gson.stream;

import java.io.*;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.ArgumentCaptor;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class JsonWriter_value_TriageGen2Test {

    private StringWriter stringWriter;
    private JsonWriter jsonWriter;
    private ArgumentCaptor<String> stringArgumentCaptor;

    @Before
    public void setUp() {
        stringWriter = new StringWriter();
        jsonWriter = new JsonWriter(stringWriter);
        jsonWriter.setLenient(false);
        stringArgumentCaptor = ArgumentCaptor.forClass(String.class);
    }

    @Test
    public void testValue_Null() throws IOException {
        assertNull(jsonWriter.value(null));
    }

    @Test
    public void testValue_LimitlessNumber() throws IOException {
        try {
            jsonWriter.value(Double.POSITIVE_INFINITY);
            fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertEquals("Numeric values must be finite, but was " + Double.POSITIVE_INFINITY, e.getMessage());
        }
    }

    @Test
    public void testValue_MoreLimitlessNumber() throws IOException {
        try {
            jsonWriter.value(Double.NEGATIVE_INFINITY);
            fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertEquals("Numeric values must be finite, but was " + Double.NEGATIVE_INFINITY, e.getMessage());
        }
    }

    @Test
    public void testValue_NaN() throws IOException {
        try {
            jsonWriter.value(Double.NaN);
            fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertEquals("Numeric values must be finite, but was NaN", e.getMessage());
        }
    }

    @Test
    public void testValue_FiniteNumber() throws IOException {
        jsonWriter.value(123.45);
        verify(stringWriter).append("123.45");
    }

    @Test
    public void testValue_LenientPositiveInfinity() throws IOException {
        jsonWriter.setLenient(true);
        jsonWriter.value(Double.POSITIVE_INFINITY);
        verify(stringWriter).append("Infinity");
    }

    @Test
    public void testValue_LenientNegativeInfinity() throws IOException {
        jsonWriter.setLenient(true);
        jsonWriter.value(Double.NEGATIVE_INFINITY);
        verify(stringWriter).append("-Infinity");
    }

    @Test
    public void testValue_LenientNaN() throws IOException {
        jsonWriter.setLenient(true);
        jsonWriter.value(Double.NaN);
        verify(stringWriter).append("NaN");
    }

    @Test
    public void testValue_Zero() throws IOException {
        jsonWriter.value(0);
        verify(stringWriter).append("0");
    }

    @Test
    public void testValue_NegativeNumber() throws IOException {
        jsonWriter.value(-123.45);
        verify(stringWriter).append("-123.45");
    }

    @Test
    public void testValue_LargeNumber() throws IOException {
        jsonWriter.value(1234567890L);
        verify(stringWriter).append("1234567890");
    }

    @Test
    public void testValue_SmallNumber() throws IOException {
        jsonWriter.value(0.00123);
        verify(stringWriter).append("0.00123");
    }
}
